=== FILE: sync_fifo.v ===
`timescale 1ns/1ps
// sync_fifo: parameterizable synchronous FIFO with first-word fall-through.
// Interface: interface_spec.md. Implementation plan: microarchitecture.md.
//  - Storage: mem[DEPTH] of WIDTH bits, not reset, written only outside reset.
//  - Pointers: wr_ptr (next slot to write), rd_ptr (oldest entry), wrapping
//    from LAST = DEPTH-1 to 0 by compare, so any DEPTH >= 2 works.
//  - Occupancy: explicit count register; full/empty are compares on it.
//  - Accept: wr_acc = wr_en && !full, rd_acc = rd_en && !empty.
//  - Read port: rd_data = mem[rd_ptr] (combinational, first-word fall-through).
//  - Reset: synchronous, active low; clears pointers and count.
module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);

    localparam integer  AW         = $clog2(DEPTH);
    localparam integer  CW         = $clog2(DEPTH+1);
    localparam integer  ONE        = 1;
    localparam integer  LAST_I     = DEPTH - 1;
    localparam [AW-1:0] LAST       = LAST_I[AW-1:0];
    localparam [AW-1:0] PTR_ONE    = ONE[AW-1:0];
    localparam [CW-1:0] CNT_ONE    = ONE[CW-1:0];
    localparam [CW-1:0] FULL_COUNT = DEPTH[CW-1:0];

    // Storage (datapath, not reset)
    reg  [WIDTH-1:0] mem [0:DEPTH-1];

    // State and next state
    reg  [AW-1:0]    wr_ptr;
    reg  [AW-1:0]    wr_ptr_d;
    reg  [AW-1:0]    rd_ptr;
    reg  [AW-1:0]    rd_ptr_d;
    reg  [CW-1:0]    count_q;
    reg  [CW-1:0]    count_d;

    wire             wr_acc;
    wire             rd_acc;

    // Flags are compares on a register: no combinational path from inputs.
    assign full    = (count_q == FULL_COUNT);
    assign empty   = (count_q == {CW{1'b0}});
    assign count   = count_q;

    // The flags gate the requests: overflow and underflow policy.
    assign wr_acc  = wr_en && !full;
    assign rd_acc  = rd_en && !empty;

    // First-word fall-through read port.
    assign rd_data = mem[rd_ptr];

    // Next write pointer
    always @(*) begin
        wr_ptr_d = wr_ptr;
        if (wr_acc) begin
            if (wr_ptr == LAST) begin
                wr_ptr_d = {AW{1'b0}};
            end else begin
                wr_ptr_d = wr_ptr + PTR_ONE;
            end
        end
    end

    // Next read pointer
    always @(*) begin
        rd_ptr_d = rd_ptr;
        if (rd_acc) begin
            if (rd_ptr == LAST) begin
                rd_ptr_d = {AW{1'b0}};
            end else begin
                rd_ptr_d = rd_ptr + PTR_ONE;
            end
        end
    end

    // Next count: +1 on write only, -1 on read only, hold otherwise.
    always @(*) begin
        count_d = count_q;
        if (wr_acc && !rd_acc) begin
            count_d = count_q + CNT_ONE;
        end else if (rd_acc && !wr_acc) begin
            count_d = count_q - CNT_ONE;
        end
    end

    // Control registers: synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr  <= {AW{1'b0}};
            rd_ptr  <= {AW{1'b0}};
            count_q <= {CW{1'b0}};
        end else begin
            wr_ptr  <= wr_ptr_d;
            rd_ptr  <= rd_ptr_d;
            count_q <= count_d;
        end
    end

    // Storage write, only outside reset and only for an accepted write.
    always @(posedge clk) begin
        if (rst_n && wr_acc) begin
            mem[wr_ptr] <= wr_data;
        end
    end

`ifdef FORMAL
    // ------------------------------------------------------------------
    // Design-intent properties (microarchitecture.md section 6).
    // ------------------------------------------------------------------
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk)
        f_past_valid <= 1'b1;

    // Reset is active in the first cycle.
    always @(*)
        if (!f_past_valid)
            assume (!rst_n);

    // One solver-chosen slot.
    (* anyconst *) reg [AW-1:0] f_addr;
    always @(*)
        assume (f_addr <= LAST);

    // The word most recently written to that slot.
    reg [WIDTH-1:0] f_data;
    always @(posedge clk)
        if (rst_n && wr_acc && (wr_ptr == f_addr))
            f_data <= wr_data;

    wire [31:0] f_wr32   = {{(32-AW){1'b0}}, wr_ptr};
    wire [31:0] f_rd32   = {{(32-AW){1'b0}}, rd_ptr};
    wire [31:0] f_cnt32  = {{(32-CW){1'b0}}, count_q};
    wire [31:0] f_adr32  = {{(32-AW){1'b0}}, f_addr};
    wire [31:0] f_dep32  = DEPTH;
    wire [31:0] f_sum32  = f_rd32 + f_cnt32;
    wire [31:0] f_wr_exp = (f_sum32 >= f_dep32) ? (f_sum32 - f_dep32) : f_sum32;
    wire [31:0] f_off    = (f_adr32 >= f_rd32) ? (f_adr32 - f_rd32)
                                               : (f_adr32 + f_dep32 - f_rd32);
    wire        f_occupied = (f_off < f_cnt32);

    // State invariants
    always @(*) begin
        if (f_past_valid) begin
            assert (f_cnt32 <= f_dep32);
            assert (f_wr32 <= (f_dep32 - 32'd1));
            assert (f_rd32 <= (f_dep32 - 32'd1));
            assert (full  == (count_q == FULL_COUNT));
            assert (empty == (count_q == {CW{1'b0}}));
            assert (!(full && empty));
            assert (f_wr32 == f_wr_exp);
            if (f_occupied)
                assert (mem[f_addr] == f_data);
            if (f_occupied && (rd_ptr == f_addr))
                assert (rd_data == f_data);
        end
    end

    // Transition properties
    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert (count_q == {CW{1'b0}});
                assert (wr_ptr  == {AW{1'b0}});
                assert (rd_ptr  == {AW{1'b0}});
                assert (empty);
                assert (!full);
            end else begin
                // count moves by exactly the accepted requests
                if ($past(wr_acc) && !$past(rd_acc))
                    assert (count_q == ($past(count_q) + CNT_ONE));
                else if ($past(rd_acc) && !$past(wr_acc))
                    assert (count_q == ($past(count_q) - CNT_ONE));
                else
                    assert (count_q == $past(count_q));

                // pointers move only on accepted requests
                if ($past(wr_acc))
                    assert (wr_ptr == (($past(wr_ptr) == LAST) ? {AW{1'b0}}
                                                               : ($past(wr_ptr) + PTR_ONE)));
                else
                    assert (wr_ptr == $past(wr_ptr));
                if ($past(rd_acc))
                    assert (rd_ptr == (($past(rd_ptr) == LAST) ? {AW{1'b0}}
                                                               : ($past(rd_ptr) + PTR_ONE)));
                else
                    assert (rd_ptr == $past(rd_ptr));

                // a write while full changes nothing on the write side
                if ($past(wr_en) && $past(full)) begin
                    assert (wr_ptr == $past(wr_ptr));
                    assert (mem[f_addr] == $past(mem[f_addr]));
                    if (!$past(rd_en))
                        assert (count_q == FULL_COUNT);
                end

                // a read while empty changes nothing on the read side
                if ($past(rd_en) && $past(empty)) begin
                    assert (rd_ptr == $past(rd_ptr));
                    if (!$past(wr_en))
                        assert (count_q == {CW{1'b0}});
                end
            end
        end
    end

    // Covers: the proof must not be vacuous.
    reg f_was_full;
    always @(posedge clk)
        if (!rst_n)
            f_was_full <= 1'b0;
        else if (full)
            f_was_full <= 1'b1;

    always @(*) begin
        if (f_past_valid && rst_n) begin
            cover (full);
            cover (wr_en && !rd_en && full);
            cover (rd_en && !wr_en && empty);
            cover (wr_en && rd_en && empty);
            cover (wr_en && rd_en && full);
            cover (wr_acc && rd_acc);
            cover (wr_acc && (wr_ptr == LAST));
            cover (rd_acc && (rd_ptr == LAST));
            cover (rd_acc && (rd_ptr == f_addr) && f_occupied);
            cover (f_was_full && empty);
        end
    end
`endif

endmodule
=== END FILE ===
=== FILE: sync_fifo_tb.v ===
`timescale 1ns/1ps
// Self-checking testbench for sync_fifo (interface_spec.md section 7).
// Two FIFOs share one stimulus: DEPTH 8 x WIDTH 8 and DEPTH 5 x WIDTH 12.
// Each has a reference-queue scoreboard that checks count, full, empty and
// rd_data on every cycle and counts coverage goals.
module sync_fifo_tb;

    localparam integer DEPTH_A = 8;
    localparam integer WIDTH_A = 8;
    localparam integer DEPTH_B = 5;
    localparam integer WIDTH_B = 12;
    localparam integer CW_A    = $clog2(DEPTH_A + 1);
    localparam integer CW_B    = $clog2(DEPTH_B + 1);

    reg                clk;
    reg                rst_n;
    reg                wr_en;
    reg                rd_en;
    reg  [WIDTH_B-1:0] wr_data;
    reg                done;

    wire               full_a;
    wire               empty_a;
    wire               full_b;
    wire               empty_b;
    wire [WIDTH_A-1:0] rd_data_a;
    wire [WIDTH_B-1:0] rd_data_b;
    wire [CW_A-1:0]    count_a;
    wire [CW_B-1:0]    count_b;
    wire [31:0]        passed_a;
    wire [31:0]        failed_a;
    wire [31:0]        passed_b;
    wire [31:0]        failed_b;

    reg  [8*64-1:0]    nonce;
    reg  [31:0]        r;
    reg  [31:0]        rr;
    reg  [7:0]         wr_th;
    reg  [7:0]         rd_th;
    reg                rst_v;
    reg  [31:0]        total_pass;
    reg  [31:0]        total_fail;
    integer            ok;
    integer            i;
    integer            phase;

    initial clk = 1'b0;
    always #5 clk = ~clk;

    sync_fifo #(.DEPTH(DEPTH_A), .WIDTH(WIDTH_A)) dut_a (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data[WIDTH_A-1:0]),
        .full    (full_a),
        .rd_en   (rd_en),
        .rd_data (rd_data_a),
        .empty   (empty_a),
        .count   (count_a)
    );

    sync_fifo #(.DEPTH(DEPTH_B), .WIDTH(WIDTH_B)) dut_b (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data),
        .full    (full_b),
        .rd_en   (rd_en),
        .rd_data (rd_data_b),
        .empty   (empty_b),
        .count   (count_b)
    );

    fifo_scoreboard #(.DEPTH(DEPTH_A), .WIDTH(WIDTH_A)) sb_a (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .rd_en   (rd_en),
        .wr_data (wr_data[WIDTH_A-1:0]),
        .full    (full_a),
        .empty   (empty_a),
        .rd_data (rd_data_a),
        .count   (count_a),
        .done    (done),
        .passed  (passed_a),
        .failed  (failed_a)
    );

    fifo_scoreboard #(.DEPTH(DEPTH_B), .WIDTH(WIDTH_B)) sb_b (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .rd_en   (rd_en),
        .wr_data (wr_data),
        .full    (full_b),
        .empty   (empty_b),
        .rd_data (rd_data_b),
        .count   (count_b),
        .done    (done),
        .passed  (passed_b),
        .failed  (failed_b)
    );

    // Apply one cycle of stimulus, away from the rising edge.
    task drive(input w, input rd_i, input rst_i);
        begin
            @(negedge clk);
            #1;
            r       = $random;
            wr_data = r[WIDTH_B-1:0];
            wr_en   = w;
            rd_en   = rd_i;
            rst_n   = rst_i;
        end
    endtask

    initial begin
        nonce      = {512{1'b0}};
        ok         = $value$plusargs("nirmaan_nonce=%s", nonce);
        rst_n      = 1'b0;
        wr_en      = 1'b0;
        rd_en      = 1'b0;
        wr_data    = {WIDTH_B{1'b0}};
        done       = 1'b0;
        wr_th      = 8'd0;
        rd_th      = 8'd0;
        rst_v      = 1'b1;
        r          = 32'd0;
        rr         = 32'd0;
        total_pass = 32'd0;
        total_fail = 32'd0;

        // Reset
        drive(1'b0, 1'b0, 1'b0);
        drive(1'b0, 1'b0, 1'b0);

        // Read while empty (ignored)
        drive(1'b0, 1'b1, 1'b1);
        drive(1'b0, 1'b1, 1'b1);

        // Write and read together while empty (only the write is accepted)
        drive(1'b1, 1'b1, 1'b1);

        // Fill to full, then keep writing (writes while full are dropped);
        // the write pointer wraps on both FIFOs.
        for (i = 0; i < 10; i = i + 1)
            drive(1'b1, 1'b0, 1'b1);

        // Write and read together when full, then in between
        for (i = 0; i < 3; i = i + 1)
            drive(1'b1, 1'b1, 1'b1);

        // Drain to empty, then keep reading (reads while empty ignored);
        // the read pointer wraps on both FIFOs.
        for (i = 0; i < 12; i = i + 1)
            drive(1'b0, 1'b1, 1'b1);

        // Reset during traffic
        for (i = 0; i < 4; i = i + 1)
            drive(1'b1, 1'b0, 1'b1);
        drive(1'b1, 1'b1, 1'b0);
        drive(1'b1, 1'b1, 1'b0);
        drive(1'b0, 1'b0, 1'b1);

        // Random traffic with stalls on both sides, several biases,
        // and one reset in the middle of heavy traffic.
        for (phase = 0; phase < 6; phase = phase + 1) begin
            case (phase)
                0:       begin wr_th = 8'd200; rd_th = 8'd60;  end
                1:       begin wr_th = 8'd60;  rd_th = 8'd200; end
                2:       begin wr_th = 8'd128; rd_th = 8'd128; end
                3:       begin wr_th = 8'd230; rd_th = 8'd230; end
                4:       begin wr_th = 8'd40;  rd_th = 8'd40;  end
                5:       begin wr_th = 8'd180; rd_th = 8'd150; end
                default: begin wr_th = 8'd128; rd_th = 8'd128; end
            endcase
            for (i = 0; i < 400; i = i + 1) begin
                rr    = $random;
                rst_v = !((phase == 3) && (i >= 200) && (i < 202));
                drive(rr[7:0] < wr_th, rr[15:8] < rd_th, rst_v);
            end
        end

        // Idle, then ask the scoreboards for their coverage verdicts.
        drive(1'b0, 1'b0, 1'b1);
        drive(1'b0, 1'b0, 1'b1);
        drive(1'b0, 1'b0, 1'b1);
        @(negedge clk);
        #1;
        done = 1'b1;
        repeat (3) @(negedge clk);
        #1;

        total_pass = passed_a + passed_b;
        total_fail = failed_a + failed_b;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, total_pass, total_fail);
        $finish;
    end

endmodule

// Reference-queue scoreboard for one sync_fifo instance.
// The model updates on the rising edge from the inputs and its own state;
// the DUT outputs are compared with it on the falling edge.
// Coverage goals: 1 full, 2 write while full, 3 drain to empty,
// 4 read while empty, 5 write+read when empty, 6 write+read when full,
// 7 write+read in between, 8 write pointer wrap, 9 read pointer wrap,
// 10 reset during traffic.
module fifo_scoreboard #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire                       rd_en,
    input  wire [WIDTH-1:0]           wr_data,
    input  wire                       full,
    input  wire                       empty,
    input  wire [WIDTH-1:0]           rd_data,
    input  wire [$clog2(DEPTH+1)-1:0] count,
    input  wire                       done,
    output reg  [31:0]                passed,
    output reg  [31:0]                failed
);

    localparam integer CW = $clog2(DEPTH + 1);

    reg  [WIDTH-1:0] q [0:DEPTH-1];
    integer          head;
    integer          tail;
    reg  [31:0]      n;
    reg              armed;
    reg              reported;

    reg  [31:0]      cov_full;
    reg  [31:0]      cov_wr_full;
    reg  [31:0]      cov_drain;
    reg  [31:0]      cov_rd_empty;
    reg  [31:0]      cov_both_empty;
    reg  [31:0]      cov_both_full;
    reg  [31:0]      cov_both_mid;
    reg  [31:0]      cov_wr_wrap;
    reg  [31:0]      cov_rd_wrap;
    reg  [31:0]      cov_rst;

    wire [31:0]      count32 = {{(32-CW){1'b0}}, count};
    wire             m_wr    = wr_en && (n < DEPTH);
    wire             m_rd    = rd_en && (n != 32'd0);

    initial begin
        passed          = 32'd0;
        failed          = 32'd0;
        reported        = 1'b0;
        armed          <= 1'b0;
        cov_full       <= 32'd0;
        cov_wr_full    <= 32'd0;
        cov_drain      <= 32'd0;
        cov_rd_empty   <= 32'd0;
        cov_both_empty <= 32'd0;
        cov_both_full  <= 32'd0;
        cov_both_mid   <= 32'd0;
        cov_wr_wrap    <= 32'd0;
        cov_rd_wrap    <= 32'd0;
        cov_rst        <= 32'd0;
    end

    // Reference model and coverage, on the rising edge.
    always @(posedge clk) begin
        if (!rst_n) begin
            if (armed && (n != 32'd0))
                cov_rst <= cov_rst + 32'd1;
            head  <= 0;
            tail  <= 0;
            n     <= 32'd0;
            armed <= 1'b1;
        end else if (armed) begin
            if (m_wr) begin
                q[tail] <= wr_data;
                tail    <= (tail == DEPTH - 1) ? 0 : tail + 1;
            end
            if (m_rd)
                head <= (head == DEPTH - 1) ? 0 : head + 1;
            if (m_wr && !m_rd)
                n <= n + 32'd1;
            else if (m_rd && !m_wr)
                n <= n - 32'd1;

            if (n == DEPTH)
                cov_full <= cov_full + 32'd1;
            if (wr_en && !rd_en && (n == DEPTH))
                cov_wr_full <= cov_wr_full + 32'd1;
            if (m_rd && !m_wr && (n == 32'd1))
                cov_drain <= cov_drain + 32'd1;
            if (rd_en && !wr_en && (n == 32'd0))
                cov_rd_empty <= cov_rd_empty + 32'd1;
            if (wr_en && rd_en && (n == 32'd0))
                cov_both_empty <= cov_both_empty + 32'd1;
            if (wr_en && rd_en && (n == DEPTH))
                cov_both_full <= cov_both_full + 32'd1;
            if (wr_en && rd_en && (n != 32'd0) && (n < DEPTH))
                cov_both_mid <= cov_both_mid + 32'd1;
            if (m_wr && (tail == DEPTH - 1))
                cov_wr_wrap <= cov_wr_wrap + 32'd1;
            if (m_rd && (head == DEPTH - 1))
                cov_rd_wrap <= cov_rd_wrap + 32'd1;
        end
    end

    task goal(input [31:0] hits, input integer id);
        begin
            if (hits != 32'd0) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("sync_fifo DEPTH=%0d: coverage goal %0d not reached (1 full, 2 write while full, 3 drain to empty, 4 read while empty, 5 write+read when empty, 6 write+read when full, 7 write+read in between, 8 write pointer wrap, 9 read pointer wrap, 10 reset during traffic)", DEPTH, id);
            end
        end
    endtask

    // Output checks, on the falling edge.
    always @(negedge clk) begin
        if (armed) begin
            if (count32 === n) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("sync_fifo DEPTH=%0d: count is %0d, expected %0d at %0t", DEPTH, count32, n, $time);
            end

            if (full === (n == DEPTH)) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("sync_fifo DEPTH=%0d: full is %b, expected %b at %0t", DEPTH, full, (n == DEPTH), $time);
            end

            if (empty === (n == 32'd0)) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("sync_fifo DEPTH=%0d: empty is %b, expected %b at %0t", DEPTH, empty, (n == 32'd0), $time);
            end

            if (!(full && empty)) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("sync_fifo DEPTH=%0d: full and empty both high at %0t", DEPTH, $time);
            end

            if (n != 32'd0) begin
                if (rd_data === q[head]) begin
                    passed = passed + 32'd1;
                end else begin
                    failed = failed + 32'd1;
                    $error("sync_fifo DEPTH=%0d: rd_data is %h, expected %h at %0t", DEPTH, rd_data, q[head], $time);
                end
            end
        end

        if (done && !reported) begin
            reported = 1'b1;
            goal(cov_full,       1);
            goal(cov_wr_full,    2);
            goal(cov_drain,      3);
            goal(cov_rd_empty,   4);
            goal(cov_both_empty, 5);
            goal(cov_both_full,  6);
            goal(cov_both_mid,   7);
            goal(cov_wr_wrap,    8);
            goal(cov_rd_wrap,    9);
            goal(cov_rst,        10);
        end
    end

endmodule
